(6006807, 880344, 22459, '<td valign="top">I like finding the hidden gems in this challenge. Congrats</td>', 'I like finding the hidden gems in this challenge. Congrats', '2010-05-14 06:59:39.000000', NULL, 1),
(6006808, 880223, 22459, '<td valign="top">Lovely kids in a lovely place.</td>', 'Lovely kids in a lovely place.', '2010-05-14 07:03:34.000000', NULL, 1),
(6006810, 878944, 22459, '<td valign="top">very nice image although the glow around the subject distracts a little</td>', 'very nice image although the glow around the subject distracts a little', '2010-05-14 07:05:41.000000', NULL, 1),
(6006819, 878696, 100335, '<td valign="top">Wow. In love with this! Expression is gold, beautiful natural light and processing is just right. Easy 10 and fave from a portraits lover.</td>', 'Wow. In love with this! Expression is gold, beautiful natural light and processing is just right. Easy 10 and fave from a portraits lover.', '2010-05-14 07:36:59.000000', NULL, 1),
(6006820, 880471, 100335, '<td valign="top">haha made me laugh. This really captures the joy of eating ice cream.</td>', 'haha made me laugh. This really captures the joy of eating ice cream.', '2010-05-14 07:40:21.000000', NULL, 1),
(6006822, 879984, 100335, '<td valign="top">woah! what the hell... how?? this is very unique. A hidden gem indeed!</td>', 'woah! what the hell... how?? this is very unique. A hidden gem indeed!', '2010-05-14 07:43:00.000000', NULL, 1),
(6006824, 879013, 100335, '<td valign="top">Beautiful capture of a beaten dead subject. I''m not easily impressed with flower shots so kudos to you!!</td>', 'Beautiful capture of a beaten dead subject. I''m not easily impressed with flower shots so kudos to you!!', '2010-05-14 07:44:08.000000', NULL, 1),
(6006826, 878594, 100335, '<td valign="top">Wow. What an intense expression and wonderful moment caught. The father''s expression is worth a million dollars. I really love this image. I think i cried a little T_T</td>', 'Wow. What an intense expression and wonderful moment caught. The father''s expression is worth a million dollars. I really love this image. I think i cried a little T_T', '2010-05-14 07:47:58.000000', NULL, 1),
(6006834, 879998, 86218, '<td valign="top">Lovely shot with shadows and mysterious mood created</td>', 'Lovely shot with shadows and mysterious mood created', '2010-05-14 08:00:00.000000', NULL, 1),
(6006835, 880313, 22459, '<td valign="top">Old is new and different.Lovely composition and nice B/W tones</td>', 'Old is new and different.Lovely composition and nice B/W tones', '2010-05-14 08:00:38.000000', NULL, 1),
(6006840, 879674, 86218, '<td valign="top">I like this. Classic sunset and old SA scene. Wonder if there could be any other country where this scene could have been shot. Colours and silouette just great</td>', 'I like this. Classic sunset and old SA scene. Wonder if there could be any other country where this scene could have been shot. Colours and silouette just great', '2010-05-14 08:07:38.000000', NULL, 1),
(6006842, 880266, 86218, '<td valign="top">Beautifull x 3. Just plain and simple beaut. Lighting maybe a bit to much at top but just a small nit for me.</td>', 'Beautifull x 3. Just plain and simple beaut. Lighting maybe a bit to much at top but just a small nit for me.', '2010-05-14 08:09:21.000000', NULL, 1),
(6006848, 878757, 12674, '<td valign="top">Good title, draws attention well to the reflections, which make the shot much more interesting.</td>', 'Good title, draws attention well to the reflections, which make the shot much more interesting.', '2010-05-14 08:23:20.000000', NULL, 1),
(6006854, 879936, 100335, '<td valign="top">great photo but shame about the hues around the trees, is that abberation or overuse of USM? cant tell. Wonderful image overall though.</td>', 'great photo but shame about the hues around the trees, is that abberation or overuse of USM? cant tell. Wonderful image overall though.', '2010-05-14 08:39:29.000000', NULL, 1),
