(6010331, 880353, 42495, '<td valign="top">I really, really like the lighting of this, but the way she''s tilted back seems a bit unnatural, IMO.</td>', 'I really, really like the lighting of this, but the way she''s tilted back seems a bit unnatural, IMO.', '2010-05-17 01:07:47.000000', NULL, 1),
(6010548, 878619, 18778, '<td valign="top">The water is beautiful- but your model looks like she''s missing her legs!  It overall looks amputated.</td>', 'The water is beautiful- but your model looks like she''s missing her legs!  It overall looks amputated.', '2010-05-17 02:15:36.000000', NULL, 1),
(6010557, 879832, 51436, '<td valign="top">Title really makes it extraordinary.</td>', 'Title really makes it extraordinary.', '2010-05-17 02:21:47.000000', NULL, 1),
(6010602, 878938, 104841, '<td valign="top">while it is an interesting shot, it has a bit too much of a computerised feel form me. That is it appears that use use one of the art filters in photoshop.</td>', 'while it is an interesting shot, it has a bit too much of a computerised feel form me. That is it appears that use use one of the art filters in photoshop.', '2010-05-17 02:55:12.000000', NULL, 1),
(6010603, 879889, 104841, '<td valign="top">nice time of day for this type of shot with those soft blues. It is a little bit of a shame there was not some more cloud cover at the time you shot, definitely a place to go back to.</td>', 'nice time of day for this type of shot with those soft blues. It is a little bit of a shame there was not some more cloud cover at the time you shot, definitely a place to go back to.', '2010-05-17 02:56:45.000000', NULL, 1),
(6010604, 880360, 104841, '<td valign="top">Nice mono conversion, I feel that the shot is a little bit unbalanced in terms or tone, light on the left and dark on the right. Maybe if you went for more of a square crop around the bridge?</td>', 'Nice mono conversion, I feel that the shot is a little bit unbalanced in terms or tone, light on the left and dark on the right. Maybe if you went for more of a square crop around the bridge?', '2010-05-17 02:58:24.000000', NULL, 1),
(6010605, 880004, 104841, '<td valign="top">you must have waited ages to get the light to peep though the clouds like this. Compositionally I think the shot is fine, though it might have been better with slightly more cliff in frame. Other then that good shot.</td>', 'you must have waited ages to get the light to peep though the clouds like this. Compositionally I think the shot is fine, though it might have been better with slightly more cliff in frame. Other then that good shot.', '2010-05-17 02:59:36.000000', NULL, 1),
