INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6015058, 880344, 96751, '<td valign="top">I still think this is the best of the bunch.  It is so moving and mysterious.  I just want to stare at it for hours.</td>', 'I still think this is the best of the bunch.  It is so moving and mysterious.  I just want to stare at it for hours.', '2010-05-19 05:14:34.000000', NULL, 0),
(6015061, 879803, 28742, '<td valign="top">Whaaaat?? Looks like the voters gave you a toughie toughie time too. :( Well, I like it and you and I both know that''s all that matters. ;-)</td>', 'Whaaaat?? Looks like the voters gave you a toughie toughie time too. :( Well, I like it and you and I both know that''s all that matters. ;-)', '2010-05-19 05:17:14.000000', NULL, 0),
(6015065, 878891, 78964, '<td valign="top">I''m very honored to receive this ribbon. I was only expecting to be in the top 10 but not the 1st place. Kudos to all the brilliant photographers who has shared their photographs too. Can''t thank everyone enough for the votes and the wonderful comments. I''ll never forget this day. <br/> <br/>By the way, I''m very lucky to get this image as after I took this shot, the mist was already gone and the light was already to bright to get a long exposure. The first shot I took of this scene was garbage because I nudged the tripod by accident. This really is a hidden gem for me. <br/> <br/>Thanks again everyone!<br/><br/><i>Message edited by author 2010-05-19 04:44:07.</i></td>', 'I''m very honored to receive this ribbon. I was only expecting to be in the top 10 but not the 1st place. Kudos to all the brilliant photographers who has shared their photographs too. Can''t thank everyone enough for the votes and the wonderful comments. I''ll never forget this day.  By the way, I''m very lucky to get this image as after I took this shot, the mist was already gone and the light was already to bright to get a long exposure. The first shot I took of this scene was garbage because I nudged the tripod by accident. This really is a hidden gem for me.  Thanks again everyone!', '2010-05-19 05:19:15.000000', '2010-05-19 05:44:07.000000', 0),
(6015075, 878996, 20608, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by h2:</b></div><hr/><i> oh no, not the stuffed lion again </i></td></tr></table> <br/> <br/>Thank you Oliver, actually he is very much alive and real.</td>', 'Originally posted by h2: oh no, not the stuffed lion again   Thank you Oliver, actually he is very much alive and real.', '2010-05-19 05:24:30.000000', NULL, 0),
(6015096, 878891, 78964, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by hesitant:</b></div><hr/><i> I like this picture so much I''ve been telling people about it all week. However, there appears to be a curious horizontal line across the middle of it which just took the edge off for me during voting. I''m still happy to see it here though - it''s a classic. </i></td></tr></table> <br/> <br/>Hesitant thank you so much for the comment. That line across the middle is actually a mountain trail. That''s where we passed by going to the summit of Mt. Pulag, here in the Philippines. I wanted to save as much detail as I could that''s why I didn''t clone or remove the line.</td>', 'Originally posted by hesitant: I like this picture so much I''ve been telling people about it all week. However, there appears to be a curious horizontal line across the middle of it which just took the edge off for me during voting. I''m still happy to see it here though - it''s a classic.   Hesitant thank you so much for the comment. That line across the middle is actually a mountain trail. That''s where we passed by going to the summit of Mt. Pulag, here in the Philippines. I wanted to save as much detail as I could that''s why I didn''t clone or remove the line.', '2010-05-19 05:33:43.000000', NULL, 0),
(6015104, 880385, 78964, '<td valign="top">I knew this image was yours. Your trademark landscape shot. Congratulations!</td>', 'I knew this image was yours. Your trademark landscape shot. Congratulations!', '2010-05-19 05:37:05.000000', NULL, 0),
